    try3 {
        let cmd = "curl -s -L --max-time " + to_string(timeout)
        if not verify {
            cmd += " --insecure"
        }
        for h in headers {
            cmd += " -H \"" + h + "\""
        }
        for c in cookies {
            cmd += " -b \"" + c + "\""
        }
        cmd += " \"" + url + "\""
        return shell(cmd)
    } uncertain {
